s=p.read_text(); old=json.loads(s[s.index('['):s.rindex(']')+1]);existing={(r['title'].lower(),r['year']) for r in old}
# All plot/content evidence is paraphrased from the linked Common Sense Media parental reviews.
movies=[
{'title':'The Mitchells vs. the Machines','year':2021,'genre':'Animation · Family','runtime':'1h 53m','officialRating':'PG','synopsis':'A family road trip turns into a fight for survival when an artificial-intelligence uprising threatens humanity.','verdict':'edifying','verdictRationale':'Provisional: reconciliation between parent and child, courage, and family solidarity form the heart of this adventure. The fast-paced action and brief relationship references merit discussion; the message of listening and restoring strained relationships is its strongest virtue.','age':'10+','ageRationale':'Frequent robot attacks, destruction, peril, and some language; older children will better understand the family tensions and satire.','pos':[('Family and responsibility',5,'The family learns to care and cooperate even through deep disagreements.'),('Forgiveness and reconciliation',4,'Katie and her father work through distance and misunderstanding.'),('Courage and hope',4,'Relatives defend and rescue one another despite extreme danger.')],'neg':[('Violence and cruelty',3,'Repeated destructive robot action and threatened harm are played partly for comedy.'),('Profanity and blasphemy',1,'PG classification includes some language.')],'warnings':[('Animated action and peril','Moderate','Robot attacks, near-abductions, explosions, destruction, and apparent danger to family members.'),('Family conflict','Mild','Parent and teenager misunderstand and argue before reconciling.'),('Relationship references','Mild','A passing reference to a girl the teenage daughter likes.')],'reflection':'A parent and child may be certain they understand the other while failing to listen. A Coptic Orthodox family can use this story to reflect on honoring parents, attentive listening, and mutual humility, without excusing either pride or dismissiveness.','scripture':['James 1:19','Ephesians 4:2–3'],'questions':['How did the family begin to listen to one another?','Which technology habits bring us closer and which distract us?','How could each family member practice humility after an argument?'],'source':'https://www.commonsensemedia.org/movie-reviews/the-mitchells-vs-the-machines'},
{'title':'Wonka','year':2023,'genre':'Fantasy · Musical','runtime':'1h 56m','officialRating':'PG','synopsis':'An aspiring chocolatier meets resistance from a powerful cartel but finds friends who help him pursue his dream.','verdict':'edifying','verdictRationale':'Provisional: generosity, perseverance, hospitality, and friendship are rewarded, while exploitative greed is shown as a wrong. Magical fantasy elements and some demeaning jokes are worth discussing.','age':'10+','ageRationale':'Mild threats, a gunshot not directed at someone, rude insults and humor, and some romantic content.','pos':[('Compassion and service',4,'Wonka forms friendships and helps others in need.'),('Courage and hope',4,'The central character perseveres in the face of unfair obstacles.'),('Truthfulness and integrity',3,'The narrative favors goodwill over corrupt commercial schemes.')],'neg':[('Violence and cruelty',2,'A few threatening situations and a firearm are documented.'),('Greed and materialism',3,'A powerful chocolate cartel seeks to suppress fair competition; its greed is condemned.')],'warnings':[('Threats and mild peril','Mild','Some gunpoint threats and a single gunshot, with comic danger.'),('Rude or demeaning humor','Mild','Jokes at the expense of a character’s body size and other insults.'),('Fantasy and romance','Mild','Imaginative magical candy, flirtation, and brief kisses.')],'reflection':'Success is not made holy by wealth or applause but by generosity and concern for neighbors. Parents can contrast the desire to create and share with the temptation to exploit others for profit.','scripture':['1 Timothy 6:10','Philippians 2:4'],'questions':['When did friendship matter more than financial success?','Why are jokes that humiliate someone unkind?','What makes ambition morally good or bad?'],'source':'https://www.commonsensemedia.org/movie-reviews/wonka'},
{'title':'Elemental','year':2023,'genre':'Animation · Romance','runtime':'1h 43m','officialRating':'PG','synopsis':'Two very different residents of a city inhabited by elemental beings discover friendship, affection, and tensions between family duty and personal aspirations.','verdict':'neutral','verdictRationale':'Provisional: honoring sacrifices made by parents, empathy, and overcoming prejudice are positive, but the primary story is a fantasy romance about self-expression rather than explicitly spiritual formation. Families can discuss duty, gratitude, and relationships.','age':'10+','ageRationale':'Some peril involving fire and water, romantic material, and brief language or teasing.','pos':[('Family and responsibility',4,'The daughter wrestles with gratitude for parents who sacrificed for her.'),('Compassion and service',3,'Characters learn to understand communities previously viewed with suspicion.'),('Courage and hope',3,'The protagonists confront barriers and family expectations.')],'neg':[('Violence and cruelty',1,'Some comic explosions and brief dangerous situations.'),('Pride and self-glorification',2,'Anger and rigid assumptions are portrayed as problems to overcome.')],'warnings':[('Fantasy peril','Mild','Fire bursts and hazards occur in the elemental city.'),('Romance','Mild','Romantic attraction and affectionate behavior are part of the central plot.'),('Brief language','Mild','Official PG rating includes brief language.')],'reflection':'The Christian virtue of honoring parents includes gratitude and honesty, yet love also calls for patient conversation rather than resentment. The story allows families to discuss how mercy can heal prejudice.','scripture':['Exodus 20:12','Colossians 3:13'],'questions':['How does gratitude for parents coexist with personal responsibility?','How did fear of differences affect the characters?'],'source':'https://www.commonsensemedia.org/movie-reviews/elemental'},
{'title':'Transformers One','year':2024,'genre':'Animation · Action','runtime':'1h 44m','officialRating':'PG','synopsis':'Two friends on Cybertron rise against injustice and develop sharply different responses to betrayal and power.','verdict':'neutral','verdictRationale':'Provisional: teamwork and courage are constructive, while a friend’s descent toward revenge invites reflection on anger and power. The film remains a combat-heavy science-fiction origin story rather than principally edifying entertainment.','age':'10+','ageRationale':'Sustained animated battles, explosions, peril, robotic injuries and deaths, and some language.','pos':[('Courage and hope',4,'Orion and his companions challenge injustice while risking harm.'),('Truthfulness and integrity',3,'Concealed abuses of power become central to the conflict.'),('Family and responsibility',2,'Loyalty between friends gives way to a morally significant division.')],'neg':[('Violence and cruelty',4,'Frequent explosive battles, peril, injuries, and deaths in robotic form.'),('Pride and self-glorification',3,'Power and vengeance contribute to a central character’s moral collapse.')],'warnings':[('Sustained sci-fi violence','Strong','Frequent combat, blasts, injury and deaths of animated robot characters.'),('Anger and revenge','Moderate','A major friendship fractures over betrayal and competing moral choices.'),('Language','Mild','Official PG classification includes language.')],'reflection':'Feeling wronged does not give a person permission to become cruel. The contrast between former friends can lead to discussion of how anger grows when separated from humility and self-restraint.','scripture':['Ephesians 4:26–27','Romans 12:21'],'questions':['Why did the former friends respond differently to betrayal?','When does righteous concern become revenge?'],'source':'https://www.commonsensemedia.org/movie-reviews/transformers-one'},
{'title':'Spider-Man: Across the Spider-Verse','year':2023,'genre':'Animation · Superhero','runtime':'2h 20m','officialRating':'PG','synopsis':'Miles Morales travels across different Spider-Verse worlds and confronts difficult choices about responsibility, loyalty, and protecting people he loves.','verdict':'neutral','verdictRationale':'Provisional: sacrifice, loyalty, and courage feature prominently, although identity, individual choice, and authority are framed through comic-book conflict rather than Christian moral teaching. The extended violence requires age discernment.','age':'10+','ageRationale':'Intense extended animated fights, chases and destruction, emotional peril, and some language.','pos':[('Love and self-sacrifice',4,'The hero’s commitment to helping loved ones drives his choices.'),('Courage and hope',4,'Miles persists despite powerful opponents and uncertain outcomes.'),('Family and responsibility',3,'Parent-child trust and secrecy are prominent conflicts.')],'neg':[('Violence and cruelty',4,'Repeated large-scale animated combat, explosions and intense confrontations.'),('Dishonesty and betrayal',2,'Secrecy and disputed loyalties drive interpersonal conflict.')],'warnings':[('Animated violence','Strong','Extended superhero confrontations and urban-scale destruction.'),('Emotional intensity','Moderate','Family separation, secrecy, and threats to loved ones.'),('Language','Mild','Official PG classification includes some language.')],'reflection':'The desire to save others can express love, but courage must remain accountable to truth and humility. Discuss the tension between duty, obedience, and a conscience informed by love.','scripture':['John 15:13','Proverbs 3:5–6'],'questions':['Does courage always mean acting alone?','Why does secrecy damage trust between children and parents?'],'source':'https://www.commonsensemedia.org/movie-reviews/spider-man-across-the-spider-verse'},
{'title':'The Garfield Movie','year':2024,'genre':'Animation · Comedy','runtime':'1h 41m','officialRating':'PG','synopsis':'Garfield reunites unexpectedly with his estranged father, Vic, and joins an adventurous rescue and heist.','verdict':'neutral','verdictRationale':'Provisional: forgiveness and family reconciliation are meaningful positives, but the light comedy, caper antics, and extensive marketing are the main entertainment frame. Some peril may surprise younger viewers.','age':'7+','ageRationale':'PG action and danger, chasing, comic threats and rude jokes.','pos':[('Forgiveness and reconciliation',4,'The reunion with Garfield’s father leads toward repaired trust.'),('Family and responsibility',3,'Garfield and his companions work to protect one another.'),('Courage and hope',3,'The characters brave threatening encounters and cooperate.')],'neg':[('Violence and cruelty',2,'Kidnapping, chases, and threats drive the adventure.'),('Greed and materialism',2,'The film contains conspicuous brand references and product placement.')],'warnings':[('Action and peril','Moderate','Characters are kidnapped, threatened, and pursued.'),('Rude humor','Mild','Some jokes involve insults or bodily humor.'),('Commercial content','Mild','Noticeable product placement and brand references.')],'reflection':'A fractured relationship can begin to heal when a person chooses mercy over rehearsing grievances. Families may also examine the difference between ordinary enjoyment and habitual consumption.','scripture':['Ephesians 4:32','Luke 6:36'],'questions':['What made reconciliation possible?','How do advertisements shape what we want?'],'source':'https://www.commonsensemedia.org/movie-reviews/the-garfield-movie'},
{'title':'Migration','year':2023,'genre':'Animation · Adventure','runtime':'1h 23m','officialRating':'PG','synopsis':'A cautious father duck takes his family beyond their familiar pond and learns to navigate dangers with courage and trust.','verdict':'neutral','verdictRationale':'Provisional: family togetherness, parental care, and courage are positive. The story remains a light comic adventure; its peril is more prominent than any explicit spiritual theme.','age':'7+','ageRationale':'Some frightening pursuit scenes featuring predators and a knife-wielding chef, and mild rude humor.','pos':[('Family and responsibility',4,'The two parents care for their children amid danger.'),('Courage and hope',3,'The family learns to face new challenges without abandoning one another.'),('Compassion and service',3,'Different birds assist and protect each other.')],'neg':[('Violence and cruelty',2,'Predators and chefs create repeated danger for the duck family.'),('Pride and self-glorification',1,'Overconfidence and rigid fear produce comic disagreement.')],'warnings':[('Peril and threats','Moderate','Dangerous encounters with predators and a chef holding knives.'),('Rude humor','Mild','Occasional bodily and verbal humor.')],'reflection':'Prudence protects a family, but fear should not become a prison. Christ teaches us to combine wise care with trust instead of allowing anxieties to govern every decision.','scripture':['Matthew 6:34','2 Timothy 1:7'],'questions':['When was the father careful, and when was he ruled by fear?','How did the family help each other under pressure?'],'source':'https://www.commonsensemedia.org/movie-reviews/migration'},
{'title':"The Magician's Elephant",'year':2023,'genre':'Animation · Fantasy','runtime':'1h 43m','officialRating':'PG','synopsis':'A boy searching for his missing sister accepts dangerous challenges while a mysterious elephant changes the outlook of a discouraged town.','verdict':'neutral','verdictRationale':'Provisional: courage, compassion, family reunion, and hope are strongly present, but fortune-telling and a magical prediction shape the plot. An Orthodox reflection should distinguish ordinary narrative fantasy from placing spiritual trust in divination.','age':'10+','ageRationale':'War memories, family loss, perilous rooftop and sword challenges, and magic or fortune-telling imagery.','pos':[('Courage and hope',4,'Peter risks much to find his missing sister.'),('Compassion and service',4,'The boy helps an elephant reunite with its own family.'),('Family and responsibility',4,'Separation and reunion drive the emotional story.')],'neg':[('Occult or misleading spirituality',2,'A fortune-teller’s prediction and conjuring are important plot elements.'),('Violence and cruelty',3,'War trauma, sword fights, and severe physical risks occur.')],'warnings':[('Peril and sadness','Moderate','War separation, apparent family deaths, animal distress, and frightening challenges.'),('Magic and divination motifs','Moderate','Fortune telling, conjuring, and supernatural-looking predictions are central narrative devices.')],'reflection':'Hope and love for family are worth encouraging, while Christians should not confuse fictional magic or fortune-telling with the trustworthy guidance of God. Discuss how discernment combines mercy with a clear spiritual foundation.','scripture':['Romans 12:12','Deuteronomy 18:10–12'],'questions':['Which choices showed compassion?','What is the difference between Christian hope and confidence in predictions?'],'source':'https://www.commonsensemedia.org/movie-reviews/the-magicians-elephant'}
]
for i,m in enumerate(movies):
    if (m['title'].lower(),m['year']) in existing:continue
    themes=[]
    for name,score,evidence in m['pos']:
        themes.append(dict(name=name,type='positive',score=score,portrayal='affirmed',evidence=evidence))
    for name,score,evidence in m['neg']:
        themes.append(dict(name=name,type='harmful',score=score,portrayal='condemned' if name in ('Greed and materialism','Pride and self-glorification') else 'descriptive',evidence=evidence))
    themes.append(dict(name='Sexual content and immodesty',type='harmful',score=None,portrayal='unverified',evidence='Complete sexual-content category not independently verified from the available summary.'))
    obj={k:m[k] for k in ['title','year','genre','runtime','officialRating','synopsis','verdict','verdictRationale','age','ageRationale','reflection','scripture','questions']}
    obj.update(id='v8-'+str(m['year'])+'-'+''.join(c if c.isalnum() else '-' for c in m['title'].lower()).strip('-'),themes=themes,warnings=[dict(name=a,severity=b,details=c) for a,b,c in m['warnings']],sources=[{'label':'Common Sense Media — movie parents guide','url':m['source'],'notes':'Factual content and plot context paraphrased; all spiritual verdicts, 0–5 theme scores, and age recommendations are independent provisional interpretations.'}],isSeed=True,isDemo=False,status='provisional',posterClass=f'p{i%6+1}',featured=False)
    old.append(obj)
p.write_text('const seedReviews = '+json.dumps(old,ensure_ascii=False,indent=2)+';\n')
print('reviews',len(old))
